DApp架构图 @startuml !theme plain skinparam backgroundColor #FEFEFE package &#34;前端层&#34; { [React应用] as react [Ethers.js库] as ethersLib [MetaMask] as mm } package &#34;区块链层&#34; { [MessageBoard.sol] as contract [以太坊测试网] as network } database &#34;链上存储&#34; { [消息列表] as messages [用户数据] as users } react -down-&gt; ethersLib : 调用 ethersLib -down-&gt; mm : 签名交易 mm -down-&gt; contract : 部署/调用 contract -down-&gt; messages : 读写 contract -down-&gt; network : 状态存储 note right of contract 智能合约功能： • 发布消息 • 查看所有消息 • 打赏消息作者 end note @enduml 正在加载图表... 步骤1：编写智能合约 // contracts/MessageBoard.sol // SPDX-License-Identifier: MIT pragma solidity ^0.8.0; contract MessageBoard { // 消息结构 struct Message { uint256 id; address author; string content; uint256 timestamp; uint256 tips; // 收到的打赏金额 } // 状态变量 Message[] public messages; mapping(address =&gt; uint256) public userMessageCount; // 事件 event MessagePosted(uint256 indexed id, address indexed author, string content); event MessageTipped(uint256 indexed id, address indexed tipper, uint256 amount); // 发布消息 function postMessage(string memory _content) public { require(bytes(_content).length &gt; 0, &#34;Content cannot be empty&#34;); require(bytes(_content).length &lt;= 280, &#34;Content too long&#34;); uint256 messageId = messages.length; messages.push(Message({ id: messageId, author: msg.sender, content: _content, timestamp: block.timestamp, tips: 0 })); userMessageCount[msg.sender]++; emit MessagePosted(messageId, msg.sender, _content); } // 打赏消息 function tipMessage(uint256 _messageId) public payable { require(_messageId &lt; messages.length, &#34;Message does not exist&#34;); require(msg.value &gt; 0, &#34;Tip must be greater than 0&#34;); Message storage message = messages[_messageId]; message.tips += msg.value; // 转账给作者 payable(message.author).transfer(msg.value); emit MessageTipped(_messageId, msg.sender, msg.value); } // 获取消息总数 function getMessageCount() public view returns (uint256) { return messages.length; } // 获取最新的N条消息 function getLatestMessages(uint256 count) public view returns (Message[] memory) { uint256 total = messages.length; uint256 returnCount = count &gt; total ? total : count; Message[] memory latestMessages = new Message[](returnCount); for (uint256 i = 0; i &lt; returnCount; i++) { latestMessages[i] = messages[total - 1 - i]; } return latestMessages; } } 步骤2：设置开发环境（Hardhat） # 创建项目目录 mkdir message-board-dapp cd message-board-dapp # 初始化npm项目 npm init -y # 安装Hardhat和依赖 npm install --save-dev hardhat @nomiclabs/hardhat-ethers ethers npm install --save-dev @nomiclabs/hardhat-waffle ethereum-waffle chai # 初始化Hardhat项目 npx hardhat # 选择：Create a JavaScript project Hardhat配置文件：
// hardhat.config.js require(&#34;@nomiclabs/hardhat-waffle&#34;); require(&#34;@nomiclabs/hardhat-ethers&#34;); module.exports = { solidity: &#34;0.8.19&#34;, networks: { hardhat: { chainId: 1337 }, sepolia: { url: &#34;https://eth-sepolia.g.alchemy.com/v2/YOUR-API-KEY&#34;, accounts: [&#34;YOUR-PRIVATE-KEY&#34;] // ⚠️ 生产环境使用环境变量 } } }; 步骤3：编写测试 // test/MessageBoard.test.js const { expect } = require(&#34;chai&#34;); const { ethers } = require(&#34;hardhat&#34;); describe(&#34;MessageBoard&#34;, function () { let messageBoard; let owner, user1, user2; beforeEach(async function () { // 获取测试账户 [owner, user1, user2] = await ethers.getSigners(); // 部署合约 const MessageBoard = await ethers.getContractFactory(&#34;MessageBoard&#34;); messageBoard = await MessageBoard.deploy(); await messageBoard.deployed(); }); it(&#34;应该能发布消息&#34;, async function () { await messageBoard.connect(user1).postMessage(&#34;Hello Web3!&#34;); const count = await messageBoard.getMessageCount(); expect(count).to.equal(1); const message = await messageBoard.messages(0); expect(message.content).to.equal(&#34;Hello Web3!&#34;); expect(message.author).to.equal(user1.address); }); it(&#34;不应该允许空消息&#34;, async function () { await expect( messageBoard.postMessage(&#34;&#34;) ).to.be.revertedWith(&#34;Content cannot be empty&#34;); }); it(&#34;应该能打赏消息&#34;, async function () { // 发布消息 await messageBoard.connect(user1).postMessage(&#34;Great content!&#34;); // 记录打赏前的余额 const balanceBefore = await ethers.provider.getBalance(user1.address); // 打赏 const tipAmount = ethers.utils.parseEther(&#34;0.1&#34;); await messageBoard.connect(user2).tipMessage(0, { value: tipAmount }); // 验证余额变化 const balanceAfter = await ethers.provider.getBalance(user1.address); expect(balanceAfter.sub(balanceBefore)).to.equal(tipAmount); // 验证消息的tips字段 const message = await messageBoard.messages(0); expect(message.tips).to.equal(tipAmount); }); it(&#34;应该能获取最新消息&#34;, async function () { // 发布多条消息 await messageBoard.postMessage(&#34;Message 1&#34;); await messageBoard.postMessage(&#34;Message 2&#34;); await messageBoard.postMessage(&#34;Message 3&#34;); // 获取最新2条 const latestMessages = await messageBoard.getLatestMessages(2); expect(latestMessages.length).to.equal(2); expect(latestMessages[0].content).to.equal(&#34;Message 3&#34;); expect(latestMessages[1].content).to.equal(&#34;Message 2&#34;); }); }); 运行测试：
npx hardhat test # 输出： # MessageBoard # ✓ 应该能发布消息 # ✓ 不应该允许空消息 # ✓ 应该能打赏消息 # ✓ 应该能获取最新消息 # # 4 passing (2s) 步骤4：部署合约 // scripts/deploy.js const hre = require(&#34;hardhat&#34;); async function main() { console.log(&#34;开始部署 MessageBoard 合约...&#34;); const MessageBoard = await hre.ethers.getContractFactory(&#34;MessageBoard&#34;); const messageBoard = await MessageBoard.deploy(); await messageBoard.deployed(); console.log(&#34;✅ MessageBoard 已部署到:&#34;, messageBoard.address); console.log(&#34;📋 请保存此地址，前端需要使用&#34;); // 验证部署 const count = await messageBoard.getMessageCount(); console.log(&#34;初始消息数:&#34;, count.toString()); } main() .then(() =&gt; process.exit(0)) .catch((error) =&gt; { console.error(error); process.exit(1); }); 部署到本地网络：
