// frontend/src/config/contract.js export const CONTRACT_ADDRESS = &#34;0x5FbDB2315678afecb367f032d93F642f64180aa3&#34;; export const CONTRACT_ABI = [ &#34;function postMessage(string memory _content) public&#34;, &#34;function tipMessage(uint256 _messageId) public payable&#34;, &#34;function getMessageCount() public view returns (uint256)&#34;, &#34;function getLatestMessages(uint256 count) public view returns (tuple(uint256 id, address author, string content, uint256 timestamp, uint256 tips)[])&#34;, &#34;event MessagePosted(uint256 indexed id, address indexed author, string content)&#34;, &#34;event MessageTipped(uint256 indexed id, address indexed tipper, uint256 amount)&#34; ]; 主应用组件：
// frontend/src/App.js import React, { useState, useEffect } from &#39;react&#39;; import { ethers } from &#39;ethers&#39;; import { CONTRACT_ADDRESS, CONTRACT_ABI } from &#39;./config/contract&#39;; import &#39;./App.css&#39;; function App() { const [account, setAccount] = useState(&#39;&#39;); const [contract, setContract] = useState(null); const [messages, setMessages] = useState([]); const [newMessage, setNewMessage] = useState(&#39;&#39;); const [loading, setLoading] = useState(false); // 连接钱包 const connectWallet = async () =&gt; { try { if (!window.ethereum) { alert(&#39;请安装MetaMask&#39;); return; } const accounts = await window.ethereum.request({ method: &#39;eth_requestAccounts&#39; }); const provider = new ethers.providers.Web3Provider(window.ethereum); const signer = provider.getSigner(); const contractInstance = new ethers.Contract( CONTRACT_ADDRESS, CONTRACT_ABI, signer ); setAccount(accounts[0]); setContract(contractInstance); // 加载消息 loadMessages(contractInstance); } catch (error) { console.error(&#39;连接失败:&#39;, error); } }; // 加载消息列表 const loadMessages = async (contractInstance) =&gt; { try { const messageList = await contractInstance.getLatestMessages(20); const formattedMessages = messageList.map(msg =&gt; ({ id: msg.id.toNumber(), author: msg.author, content: msg.content, timestamp: new Date(msg.timestamp.toNumber() * 1000).toLocaleString(), tips: ethers.utils.formatEther(msg.tips) })); setMessages(formattedMessages); } catch (error) { console.error(&#39;加载消息失败:&#39;, error); } }; // 发布消息 const postMessage = async () =&gt; { if (!newMessage.trim()) { alert(&#39;请输入消息内容&#39;); return; } setLoading(true); try { const tx = await contract.postMessage(newMessage); console.log(&#39;交易已发送:&#39;, tx.hash); await tx.wait(); console.log(&#39;消息发布成功!&#39;); setNewMessage(&#39;&#39;); await loadMessages(contract); } catch (error) { console.error(&#39;发布失败:&#39;, error); alert(&#39;发布失败: &#39; + error.message); } finally { setLoading(false); } }; // 打赏消息 const tipMessage = async (messageId) =&gt; { const amount = prompt(&#39;输入打赏金额 (ETH):&#39;); if (!amount || isNaN(amount)) return; try { const tx = await contract.tipMessage(messageId, { value: ethers.utils.parseEther(amount) }); console.log(&#39;打赏交易已发送:&#39;, tx.hash); await tx.wait(); console.log(&#39;打赏成功!&#39;); await loadMessages(contract); } catch (error) { console.error(&#39;打赏失败:&#39;, error); alert(&#39;打赏失败: &#39; + error.message); } }; // 监听新消息事件 useEffect(() =&gt; { if (contract) { contract.on(&#39;MessagePosted&#39;, (id, author, content) =&gt; { console.log(&#39;新消息:&#39;, content); loadMessages(contract); }); return () =&gt; { contract.removeAllListeners(); }; } }, [contract]); return ( &lt;div className=&#34;App&#34;&gt; &lt;header className=&#34;App-header&#34;&gt; &lt;h1&gt;📝 去中心化留言板&lt;/h1&gt; {!account ? ( &lt;button onClick={connectWallet} className=&#34;connect-btn&#34;&gt; 连接钱包 &lt;/button&gt; ) : ( &lt;p className=&#34;account&#34;&gt; {account.slice(0, 6)}...{account.slice(-4)} &lt;/p&gt; )} &lt;/header&gt; {account &amp;&amp; ( &lt;div className=&#34;container&#34;&gt; {/* 发布消息区域 */} &lt;div className=&#34;post-section&#34;&gt; &lt;textarea value={newMessage} onChange={(e) =&gt; setNewMessage(e.target.value)} placeholder=&#34;分享你的想法... (最多280字符)&#34; maxLength={280} rows={4} /&gt; &lt;div className=&#34;post-actions&#34;&gt; &lt;span&gt;{newMessage.length}/280&lt;/span&gt; &lt;button onClick={postMessage} disabled={loading} className=&#34;post-btn&#34; &gt; {loading ? &#39;发布中...&#39; : &#39;发布&#39;} &lt;/button&gt; &lt;/div&gt; &lt;/div&gt; {/* 消息列表 */} &lt;div className=&#34;messages-section&#34;&gt; &lt;h2&gt;最新消息&lt;/h2&gt; {messages.length === 0 ? ( &lt;p className=&#34;no-messages&#34;&gt;还没有消息，发布第一条吧！&lt;/p&gt; ) : ( messages.map(msg =&gt; ( &lt;div key={msg.id} className=&#34;message-card&#34;&gt; &lt;div className=&#34;message-header&#34;&gt; &lt;span className=&#34;author&#34;&gt; {msg.author.slice(0, 6)}...{msg.author.slice(-4)} &lt;/span&gt; &lt;span className=&#34;timestamp&#34;&gt;{msg.timestamp}&lt;/span&gt; &lt;/div&gt; &lt;p className=&#34;content&#34;&gt;{msg.content}&lt;/p&gt; &lt;div className=&#34;message-footer&#34;&gt; &lt;span className=&#34;tips&#34;&gt;💰 {msg.tips} ETH&lt;/span&gt; &lt;button onClick={() =&gt; tipMessage(msg.id)} className=&#34;tip-btn&#34; &gt; 打赏 &lt;/button&gt; &lt;/div&gt; &lt;/div&gt; )) )} &lt;/div&gt; &lt;/div&gt; )} &lt;/div&gt; ); } export default App; 样式文件：
